int x = 5;
const int cx = x;
int arr[3];

// 1. Value Deduction (Strips const, decay)
auto v1 = cx;     // Type: int
auto v2 = arr;    // Type: int*

// 2. Lvalue Reference Deduction (Preserves type/const)
auto& r1 = cx;    // Type: const int&
auto& r2 = x;     // Type: int&
auto& r3 = arr;   // Type: int (&)[3]

// 3. Rvalue Reference (Binds to temporaries)
auto&& u1 = 10;   // Type: int&& (rvalue)
auto&& u2 = x;    // Type: int& (lvalue reference via collapsing)
